solver:
const n = 9;
const inside = ([x, y]) => x >= 0 && x < n && y >= 0 && y < n;
const squares = new Set();
for (let x = 0; x < n; x++) {
  for (let y = 0; y < n; y++) {
    for (let a = -n; a <= n; a++) {
      for (let b = -n; b <= n; b++) {
        if (a === 0 && b === 0) continue;
        const corners = [
          [x, y],
          [x + a, y + b],
          [x + a - b, y + b + a],
          [x - b, y + a]
        ];
        if (!corners.every(inside)) continue;
        const key = corners
          .map(([cx, cy]) => cx * n + cy)
          .sort((p, q) => p - q)
          .join(',');
        squares.add(key);
      }
    }
  }
}
return squares.size;
